I used ChatGPT 5 Auto as my LLM for this assignment. I then entered in the following prompt:
"Write SystemVerilog HDL to time multiplex a single seven segment decoder (that decodes from four bits to a common anode seven segment display) to decode two sets of input bits and drive two sets of seven output bits."
This produced the following code blocks that synthesized first try:
// 4-bit hex to 7-seg decoder
// seg[6:0] = {a,b,c,d,e,f,g}, ACTIVE-LOW for common-anode displays.
module sevenseg_decode_hex_ca (
    input  logic [3:0] d,
    output logic [6:0] seg
);
    always_comb begin
        unique case (d)
            4'h0: seg = 7'b0000001; // 0
            4'h1: seg = 7'b1001111; // 1
            4'h2: seg = 7'b0010010; // 2
            4'h3: seg = 7'b0000110; // 3
            4'h4: seg = 7'b1001100; // 4
            4'h5: seg = 7'b0100100; // 5
            4'h6: seg = 7'b0100000; // 6
            4'h7: seg = 7'b0001111; // 7
            4'h8: seg = 7'b0000000; // 8
            4'h9: seg = 7'b0000100; // 9
            4'hA: seg = 7'b0001000; // A
            4'hB: seg = 7'b1100000; // b
            4'hC: seg = 7'b0110001; // C
            4'hD: seg = 7'b1000010; // d
            4'hE: seg = 7'b0110000; // E
            4'hF: seg = 7'b0111000; // F
            default: seg = 7'b1111111; // all off
        endcase
    end
endmodule
